    }

    protected function tearDown(): void
    {
        date_default_timezone_set(getenv('TZ') ?: 'Etc/UTC');
        $this->rmtree($this->tmp);
        parent::tearDown();
    }

    private function rmtree(string $path): void
    {
        if (is_dir($path)) {
            foreach (scandir($path) as $f) {
                if ($f !== '.' && $f !== '..') {
                    $this->rmtree("$path/$f");
                }
            }
            rmdir($path);
        } elseif (file_exists($path)) {
            unlink($path);
        }
    }

    /** @return array<string, mixed> */
    private static function expected(string $key): array
    {
        static $all = null;
        $all ??= json_decode(self::EXPECTED, true, 512, JSON_THROW_ON_ERROR);

        return $all[$key];
    }

    // ------------------------------------------------------------------ the scenarios (tools/gen/photos_reference.py)

    /**
     * `safe()`: the value, or the exception as `{"$error": <Python class>, "message": str(e)}`
     *
     * @return mixed
     */
    private static function safe(callable $f): mixed
    {
        try {
            return $f();
        } catch (\Throwable $e) {
            return [
                '$error' => match (true) {
                    $e instanceof \OutOfBoundsException => 'KeyError',
                    default => (new \ReflectionClass($e))->getShortName(),
                },
                'message' => Py::str($e),
            ];
        }
    }

    /** `dt()` */
    private static function dt(DateTimeInterface $d): array
    {
        return ['ts' => $d->format('U.u'), 'iso' => $d->format('Y-m-d\TH:i:s.uP')];
    }

    /** `enum_key()` */
    private static function enum_key(AssetVersionSize|LivePhotoVersionSize $k): string
    {
        return (new \ReflectionClass($k))->getShortName().'.'.$k->name;
    }

    /** `lp_filename_concatinator` of icloudpd/base.py */
    private static function lp_filename_concatinator(string $filename): string
    {
        [$name, $ext] = Os::path_splitext($filename);
        if ($ext === '') {
            return $filename;
        }

        return $name.(strtolower($ext) === '.heic' ? '_HEVC.MOV' : '.MOV');
    }

    /** `lp_filename_original` of icloudpd/base.py */
    private static function lp_filename_original(string $filename): string
    {
        [$name, $ext] = Os::path_splitext($filename);

        return $ext === '' ? $filename : $name.'.MOV';
    }

    /** `build_filename_with_policies(policy, lambda s: s, photo)` of icloudpd/filename_policies.py */
    private static function build_filename_with_policies(FileMatchPolicy $file_match_policy, PhotoAsset $photo): string
    {
        $extract_with_fallback = Photos::filename_with_fallback($photo->id(), $photo->item_type_extension());
        $raw_filename = $extract_with_fallback($photo->calculate_filename());
        $filename_cleaner_transformer = Photos::apply_filename_cleaner(fn (string $s) => $s);
        $cleaned_filename = $filename_cleaner_transformer($raw_filename);
        $policy_transformer = Photos::apply_file_match_policy($file_match_policy, $photo->id());

        return $policy_transformer($cleaned_filename);
    }

    /** `info()` (the urls are compared by sha1, see `tools/gen/gen_photos_expected.py`) */
    public static function info(PhotoAsset $p): array
    {
        $d = [];
        $d['id'] = $p->id();
        $d['calculate_filename'] = self::safe(fn () => $p->calculate_filename());
        $d['filename'] = self::safe(fn () => $p->filename());
        $d['item_type'] = self::safe(fn () => $p->item_type()?->name);
        $d['item_type_extension'] = $p->item_type_extension();
        $d['fingerprint_filename'] = Photos::generate_fingerprint_filename($p->id(), $p->item_type_extension());
        $d['filename_original_policy'] = self::safe(
            fn () => self::build_filename_with_policies(FileMatchPolicy::NAME_SIZE_DEDUP_WITH_SUFFIX, $p)
        );
        $d['filename_id7_policy'] = self::safe(
            fn () => self::build_filename_with_policies(FileMatchPolicy::NAME_ID7, $p)
        );
        $d['size'] = self::safe(fn () => $p->size());
        $d['dimensions'] = self::safe(fn () => $p->dimensions());
        $d['asset_date'] = self::safe(fn () => self::dt($p->asset_date()));
        $d['added_date'] = self::safe(fn () => self::dt($p->added_date()));
        $d['created'] = self::safe(fn () => self::dt($p->created()));
        $d['versions'] = self::safe(function () use ($p) {
            $versions = [];
            foreach ($p->versions() as $k => $v) {
                $versions[] = [
                    'key' => self::enum_key($k),
                    'size' => $v->size,
                    'type' => $v->type,
                    'checksum' => $v->checksum,
                    'filename_original' => self::safe(
                        fn () => $p->calculate_version_filename($v, $k, self::lp_filename_original(...))
                    ),
                    'filename_concat' => self::safe(
                        fn () => $p->calculate_version_filename($v, $k, self::lp_filename_concatinator(...))
                    ),
                    'url_sha1' => sha1($v->url),
                ];
            }

            return $versions;
        });
        $d['raw'] = [];
        foreach (RawTreatmentPolicy::cases() as $policy) {
            $d['raw'][$policy->name] = self::safe(function () use ($p, $policy) {
                $rows = [];
                foreach ($p->versions_with_raw_policy($policy) as $k => $v) {
                    $rows[] = [self::enum_key($k), $v->type, sha1($v->url), $v->size];
                }

                return $rows;
            });
        }
        $d['repr'] = $p->__repr__();

        return $d;
    }

    /** `compact()`, as a row of the expected listing */
    public static function row(PhotoAsset $p): string
    {
        $filename = self::safe(fn () => $p->filename());
        $item_type = self::safe(fn () => $p->item_type()?->name);
        $created = self::safe(fn () => self::dt($p->created()));
        $keys = self::safe(function () use ($p) {
            $keys = [];
            foreach ($p->versions() as $k => $_) {
                $keys[] = self::enum_key($k);
            }

            return $keys;
        });

        return implode('|', [
            $p->id(),
            self::is_err($filename) ? '!'.$filename['$error'] : $filename,
            self::is_err($item_type) ? '!'.$item_type['$error'] : ($item_type ?? '-'),
            self::is_err($created) ? '!'.$created['$error'] : $created['ts'],
            self::is_err($keys) ? '!'.$keys['$error'] : implode(',', array_map(fn ($k) => self::SHORT[$k], $keys)),
        ]);
    }

    private static function is_err(mixed $v): bool
    {
        return is_array($v) && array_key_exists('$error', $v);
    }

    /** `album_meta()` */
    private static function album_meta(PhotoAlbum $a): array
    {
        return [
            'name' => $a->name,
            'str' => Py::str($a),
            'repr' => $a->__repr__(),
            'title' => $a->title(),
            'list_type' => $a->list_type,
            'obj_type' => $a->obj_type,
            'query_filter' => $a->query_filter,
            'page_size' => $a->page_size,
            'zone_id' => $a->_zone_id,
            'offset' => $a->offset,
        ];
    }

    /** `library_of()`: `--library NAME` (the default is PrimarySync) */
    private static function library_of(PyiCloudService $icloud, string $name): PhotoLibrary
    {
        if (array_key_exists($name, $icloud->photos()->private_libraries())) {
            return $icloud->photos()->private_libraries()[$name];
        }

        return $icloud->photos()->shared_libraries()[$name];
    }

    /** `libraries()`: `--list-libraries` */
    private static function libraries(PyiCloudService $icloud): array
    {
        $names = array_unique([
            ...array_keys($icloud->photos()->private_libraries()),
            ...array_keys($icloud->photos()->shared_libraries()),
        ]);
        sort($names);
        $types = [];
        foreach ($icloud->photos()->private_libraries() + $icloud->photos()->shared_libraries() as $k => $v) {
            $types[$k] = [$v->library_type, $v->zone_id, $v->service_endpoint];
        }

        return [
            'private' => array_keys($icloud->photos()->private_libraries()),
            'shared' => array_keys($icloud->photos()->shared_libraries()),
            'union' => $names,
            'types' => $types,
        ];
    }

    /** `albums()`: `--list-albums` */
    private static function albums(PyiCloudService $icloud): array
    {
        $library = self::library_of($icloud, 'PrimarySync');
        $all_albums = $library->albums();

        return [
            'titles' => array_map(fn ($a) => Py::str($a), array_values($all_albums)),
            'albums' => array_map(self::album_meta(...), array_values($all_albums)),
            'all' => self::album_meta($library->all()),
            'recently_deleted' => self::album_meta($library->recently_deleted()),
            'service_endpoint' => $library->service_endpoint,
            'params' => $library->params,
        ];
    }

    /** `photos(n, library=...)`: `len(album)` then `islice(album, n)` (what base.py does) */
    private static function photos(int $n, string $library = 'PrimarySync'): \Closure
    {
        return function (PyiCloudService $icloud) use ($n, $library): array {
            $album = self::library_of($icloud, $library)->all();
            $count = count($album);
            $items = [];
            if ($n > 0) {
                foreach ($album as $photo) {
                    $items[] = $photo;
                    if (count($items) >= $n) {
                        break;
                    }
                }
            }

            return ['count' => $count, 'offset' => $album->offset, 'n' => count($items), 'items' => $items];
        };
    }

    /** `deleted(n)`: autodelete, `for media in library_object.recently_deleted` */
    private static function deleted(int $n): \Closure
    {
        return function (PyiCloudService $icloud) use ($n): array {
            $items = [];
            foreach (self::library_of($icloud, 'PrimarySync')->recently_deleted() as $photo) {
                $items[] = $photo;
                if (count($items) >= $n) {
                    break;
                }
            }

            return ['n' => count($items), 'items' => $items];
        };
    }

    // ------------------------------------------------------------------ replay and comparison

    /**
     * `replay()` (`run()` of tools/gen/photos_reference.py): authenticate with `tests/cookie`, call `$f`, return the result and the requests sent.
     *
     * @return array{0: mixed, 1: list<array<string, mixed>>}
     */
    private function replay(string $cassette, callable $f): array
    {
        $requests = [];
        $cookie_dir = $this->tmp.'/cookie';
        mkdir($cookie_dir, 0700);
        foreach (['jdoegmailcom', 'jdoegmailcom.session'] as $name) {
            copy(__DIR__.'/cookie/'.$name, $cookie_dir.'/'.$name);
        }

        $result = null;
        Vcr::use_cassette($cassette, function () use ($f, $cookie_dir, &$requests, &$result) {
            $replay = Session::$transport;
            Session::$transport = function (Request $request) use ($replay, &$requests) {
                $requests[] = $request;

                return $replay($request);
            };
            try {
                $icloud = new PyiCloudService(
                    'com', 'jdoe@gmail.com', fn () => 'password1', null, $cookie_dir, true, self::CLIENT_ID
                );
                $result = $f($icloud);
            } finally {
                Session::$transport = $replay;
            }
        });

        return [$result, array_map(self::request_row(...), $requests)];
    }

    /** a request as `_send()` of tools/gen/photos_reference.py logs it (the body of the list queries is compared by sha1) */
    private static function request_row(Request $request): array
    {
        [$scheme, $netloc, $path, $query] = Urllib::urlsplit($request->url);
        $body = $request->body === null || $request->body === '' ? null : json_decode($request->body, true);
        $row = [
            'method' => $request->method,
            'url' => "$scheme://$netloc$path",
            'query' => Urllib::parse_qsl($query, true),
            'body' => $body,
            'range' => $request->headers['Range'] ?? null,
            'content_type' => $request->headers['Content-type'] ?? null,
        ];
        $canon = self::canon($body);
        if ($body !== null && strlen($canon) > 400) {
            $row['body'] = null;
            $row['body_sha1'] = sha1($canon);
        }

        return $row;
    }

    /** `json.dumps(o, sort_keys=True, separators=(",", ":"))` */
    private static function canon(mixed $o): string
    {
        $sort = function (mixed $o) use (&$sort) {
            if (!is_array($o)) {
                return $o;
            }
            if (!array_is_list($o)) {
                ksort($o, SORT_STRING);
            }

            return array_map($sort, $o);
        };

        return json_encode($sort($o), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION);
    }

    /** @param list<array<string, mixed>> $expected @param list<array<string, mixed>> $actual */
    private function assertRequests(array $expected, array $actual, string $scenario): void
    {
        $this->assertSame(count($expected), count($actual), "$scenario: number of requests");
        foreach ($expected as $i => $e) {
            // `body_sha1` is only set where the Python body is too long to be kept
            $a = $actual[$i];
            $this->assertSame($e['method'].' '.$e['url'], $a['method'].' '.$a['url'], "$scenario: request #$i");
            $this->assertSame($e['query'], $a['query'], "$scenario: request #$i query");
            $this->assertSame($e['range'], $a['range'], "$scenario: request #$i Range");
            $this->assertSame($e['content_type'], $a['content_type'], "$scenario: request #$i Content-type");
            $this->assertSame($e['body'], $a['body'], "$scenario: request #$i body");
            $this->assertSame($e['body_sha1'] ?? null, $a['body_sha1'] ?? null, "$scenario: request #$i body sha1");
        }
    }

    /**
     * Compares the photos with the expected values; the rows listing is complete for some scenarios, the others
     * only keep the 3 first rows and the sha1 of all of them.
     *
     * @param list<PhotoAsset> $items
     * @param array<string, mixed> $expected
     */
    private function assertPhotos(array $items, array $expected, string $scenario): void
    {
        $this->assertGreaterThanOrEqual(count($expected['full']), count($items), "$scenario: photos");
        foreach ($expected['full'] as $i => $e) {
            $actual = self::info($items[$i]);
            foreach ($e as $key => $value) {
                if ($key === 'created_paris') {
                    continue;
                }
                $this->assertSame($value, $actual[$key], "$scenario: photo #$i $key");
            }
            // `created` in another time zone: `get_localzone()` follows the default time zone
            date_default_timezone_set('Europe/Paris');
            try {
                $this->assertSame($e['created_paris'], self::safe(fn () => self::dt($items[$i]->created())), "$scenario: photo #$i created in Europe/Paris");
            } finally {
                date_default_timezone_set(getenv('TZ') ?: 'Etc/UTC');
            }
        }
        $rows = array_map(self::row(...), $items);
        if (array_key_exists('rows', $expected)) {
            $this->assertSame($expected['rows'], $rows, "$scenario: rows");
        } else {
            $this->assertSame($expected['rows_head'], array_slice($rows, 0, 3), "$scenario: first rows");
            $this->assertSame($expected['rows_sha1'], sha1(implode("\n", $rows)), "$scenario: sha1 of the rows");
        }
    }

    /** one `<cassette>/photos` scenario of tools/gen/photos_reference.py */
    private function assertListing(string $cassette, int $n, string $scenario = 'photos', ?string $library = null): array
    {
        $key = "$cassette/$scenario";
        $expected = self::expected($key);
        $f = $scenario === 'deleted' ? self::deleted($n) : ($library === null ? self::photos($n) : self::photos($n, $library));
        [$result, $requests] = $this->replay($cassette, $f);

        $this->assertFalse(self::is_err($result), "$key: ".json_encode($result));
        $this->assertRequests($expected['requests'], $requests, $key);
        $e = $expected['result'];
        foreach (['count', 'offset', 'n'] as $k) {
            if (array_key_exists($k, $e)) {
                $this->assertSame($e[$k], $result[$k], "$key: $k");
            }
        }
        $this->assertPhotos($result['items'], $e, $key);

        return [$result, $e];
    }

