    /** 100 photos on a page, `listing_photos.yml` (test_listing_recent_photos.py) */
    public function test_listing_photos(): void
    {
        [$result, $e] = $this->assertListing('listing_photos', 100);
        // the download URLs, in clear for the first photo
        foreach ($e['urls_literal'] as $key => $url) {
            $found = false;
            foreach ($result['items'][0]->versions() as $k => $v) {
                if (self::enum_key($k) === $key) {
                    $this->assertSame($url, $v->url, $key);
                    $found = true;
                }
            }
            $this->assertTrue($found, $key);
        }
        // the recent photos listing of test_listing_recent_photos.py
        $names = [];
        foreach (array_slice($result['items'], 0, 5) as $photo) {
            foreach ($photo->versions() as $k => $v) {
                if ($k === AssetVersionSize::ORIGINAL || $k === LivePhotoVersionSize::ORIGINAL) {
                    $names[] = $photo->calculate_version_filename($v, $k, self::lp_filename_original(...));
                }
            }
        }
        $this->assertSame(
            ['IMG_7409.JPG', 'IMG_7409.MOV', 'IMG_7408.JPG', 'IMG_7408.MOV', 'IMG_7407.JPG', 'IMG_7407.MOV', 'IMG_7405.MOV', 'IMG_7404.MOV'],
            array_slice($names, 0, 8),
        );
    }

